// Zero value is ready to use with default TTL (DefaultSLMCacheTTL).
// Construct with NewSLMCache to override TTL.
type SLMCache struct {
	ttl          time.Duration
	maxEntries   int
	embedder     Embedder
	semThreshold float64 // cosine similarity floor for semantic match (0.0..1.0)

