	// With maxStale=2 and stale=2, no eviction should fire.
	c := NewSLMCache(50*time.Millisecond, 0)
	ctx := context.Background()

	c.Set(ctx, "a", RouteLocal)
	c.Set(ctx, "b", RouteLocal)

	time.Sleep(120 * time.Millisecond)

	// stale = 2
	c.SetMaxStale(2) // threshold = 2

	// Trigger getSemantic via a miss (embedder that errors so semantic path runs).
	c2 := NewSLMCacheWithEmbedder(50*time.Millisecond, 0, &vectorEmbedder{err: errors.New("fail")}, 0.5)
	c2.Set(ctx, "a", RouteLocal)
	c2.Set(ctx, "b", RouteLocal)
	time.Sleep(120 * time.Millisecond)
	c2.SetMaxStale(2)
	c2.Get(ctx, "different") // triggers getSemantic but no stale eviction expected
	time.Sleep(50 * time.Millisecond)
	if stale := c2.Stale(); stale != 2 {
		t.Errorf("Stale at exactly threshold = %d, want 2 (no eviction)", stale)
	}
}

